  "status" text,
  "jd" text,
  "posted_verified" text,
  "posted_confidence" text,
  "loc_state" text,
  "loc_metro" text,
  "remote" boolean,
  "salary_min" integer,
  "salary_max" integer,
  "salary_period" text,
  "last_seen" date,
  "is_active" boolean default true,
  "miss_count" integer default 0,
  "first_seen" date default CURRENT_DATE,
  "exp_max_years" integer,
  "sponsor_jd" text,
  "sponsor_reason" text,
  "jd_terms" text,
  constraint "jobs_pkey" PRIMARY KEY (url)
